    "description": "新华社莫斯科9月25日电（记者赵冰）俄罗斯中央选举委员会（中选委）主席帕姆菲洛娃25日公布第九届国家杜马（议会下院）选举结果，执政党统一俄罗斯党（统俄党）赢得349个席位，获得“宪法多数”地位。 帕姆菲洛娃说，根据统计数据，俄罗斯联邦共产党获得37席，位居第二；俄罗斯自由民主党获得23席，位列第三；新人党和公正俄罗斯党分别获得19席和17席。此外，祖国党获得1席，另有4名独立候选人获得4席。 帕姆菲洛娃还说，本届选举中，共有46名参与特…",
    "content": "新华社莫斯科9月25日电（记者赵冰）俄罗斯中央选举委员会（中选委）主席帕姆菲洛娃25日公布第九届国家杜马（议会下院）选举结果，执政党统一俄罗斯党（统俄党）赢得349个席位，获得“宪法多数”地位。 帕姆菲洛娃说，根据统计数据，俄罗斯联邦共产党获得37席，位居第二；俄罗斯自由民主党获得23席，位列第三；新人党和公正俄罗斯党分别获得19席和17席。此外，祖国党获得1席，另有4名独立候选人获得4席。 帕姆菲洛娃还说，本届选举中，共有46名参与特别军事行动的人员成为议员，其中41人来自统俄党。 俄罗斯第九届国家杜马选举18日…"
