    "pub_date": "2026-09-25 18:05:44",
    "author": "",
    "description": "9月24日，国新办举行“开局起步‘十五五’”系列主题新闻发布会。发布会上，文化和旅游部有关负责人介绍，“十四五”时期，我国文化和旅游发展取得明显成效。截至2025年底，全国共有公共图书馆3253个、备案博物馆7188家、群众文化机构近4.4万个，共有国家级非遗代表性项目1557项、代表性传承人3994人。",
