    "link": "https://m.thepaper.cn/detail/34149921",
    "pub_date": "2026-09-25 18:03:56",
    "author": "澎湃新闻记者 胡杰 发自日本名古屋",
    "description": "9月25日，中国女篮在爱知·名古屋亚运会的女篮半决赛争夺中以80比85不敌韩国队，遗憾无缘决赛舞台。 全场比赛中，中国女篮未能投进一个三分球。赛后被问及这一方面，中国女篮主教练宫鲁鸣对澎湃新闻记者做出了回应： “不能以一场球下定论，今年比较特别，我是觉得我们内线的优势比较大。”宫鲁鸣表示。 “但是我们内线的球回不来，我们想减速打优势，想要内外结合，但球进去了出不来，出来的球速也很慢，对方的积极防守确实给我们制造了很多困难。大家拼到极致的…",
    "content": "9月25日，中国女篮在爱知·名古屋亚运会的女篮半决赛争夺中以80比85不敌韩国队，遗憾无缘决赛舞台。 全场比赛中，中国女篮未能投进一个三分球。赛后被问及这一方面，中国女篮主教练宫鲁鸣对澎湃新闻记者做出了回应： “不能以一场球下定论，今年比较特别，我是觉得我们内线的优势比较大。”宫鲁鸣表示。 “但是我们内线的球回不来，我们想减速打优势，想要内外结合，但球进去了出不来，出来的球速也很慢，对方的积极防守确实给我们制造了很多困难。大家拼到极致的时候，体力也跟不上。” 宫鲁鸣认为，比赛中中国女篮也有空位投篮的机会，不过“得有…"
