    "title": "焦点访谈｜中秋话家风 佳节共团圆",
    "link": "https://www.chinanews.com.cn/sh/2026/09-25/10703796.shtml",
    "pub_date": "2026-09-25 18:00:42",
    "author": "",
    "description": "央视网消息(焦点访谈)：万里清辉寄乡愁，一轮明月祝团圆。中秋，是中华民族的传统佳节，也是中华优秀传统文化的重要符号之一。从9月24日起，焦点访谈推出中秋特别节目《月明千秋》。中秋节，承载着“月圆人团圆”的美好愿景，是传承中华优秀传统文化、弘扬优良家风的重要载体，更是凝聚家国情感的重要纽带。“明月几时有？把酒问青天。”九百五十年前，苏东坡举杯问月，写下这阕千古绝唱。“人有悲欢离合，月有阴晴圆缺”——正因月有圆缺，人间的团圆才更显珍贵。",
    "content": "央视网消息(焦点访谈)：万里清辉寄乡愁，一轮明月祝团圆。中秋，是中华民族的传统佳节，也是中华优秀传统文化的重要符号之一。从9月24日起，焦点访谈推出中秋特别节目《月明千秋》。中秋节，承载着“月圆人团圆”的美好愿景，是传承中华优秀传统文化、弘扬优良家风的重要载体，更是凝聚家国情感的重要纽带。“明月几时有？把酒问青天。”九百五十年前，苏东坡举杯问月，写下这阕千古绝唱。“人有悲欢离合，月有阴晴圆缺”——正因月有圆缺，人间的团圆才更显珍贵。"
