    "description": "9月24日，永升服务（01995.HK）发布公告，自同日起进行董事及主席变更、董事会委员会组成变动，以及授权代表和法律程序文件代理人变更。林中因其他事务辞任执行董事，崔晓青因其他事务辞任非执行董事。现任执行董事兼总裁林祝波获委任为董事会主席。 公告显示，林中辞任后不再担任永升服务的董事会主席，同时不再参与集团日常管理及营运，将以高级战略顾问身份继续为集团发展提供战略建议及支持。董事会感谢两人任职期间所作贡献。 知情人士向澎湃新闻表示，在…",
    "content": "9月24日，永升服务（01995.HK）发布公告，自同日起进行董事及主席变更、董事会委员会组成变动，以及授权代表和法律程序文件代理人变更。林中因其他事务辞任执行董事，崔晓青因其他事务辞任非执行董事。现任执行董事兼总裁林祝波获委任为董事会主席。 公告显示，林中辞任后不再担任永升服务的董事会主席，同时不再参与集团日常管理及营运，将以高级战略顾问身份继续为集团发展提供战略建议及支持。董事会感谢两人任职期间所作贡献。 知情人士向澎湃新闻表示，在推进旭辉控股集团化债的同时，林中一直坚持参与永升服务的战略制定与日常经营管理。考…"
