    "description": "不少大家日常觉得“小事一桩”的消防陋习，现在违法成本明显提高。 记者9月24日从广东省消防救援总队获悉，《广东省消防行政处罚裁量权基准实施细则》近日修订，并自2026年9月20日起施行，进一步收紧了部分高危消防违法行为的处罚尺度。 其中，新规明确，电动自行车违规停放、充电引发火灾，即使只烧到自家，也不在免罚范围之内。 本次新规针对高频风险作出明确调整，降低行政拘留移送门槛。在KTV、商场等公众聚集场所营业期间违规动火作业；老板、负责人指…",
