    "content": "银河如练垂落，万山侧耳倾听。2026年9月25日，“中国天眼”——500米口径球面射电望远镜（FAST）迎来落成十周年。 习近平总书记十分关心这座大国重器，十年前，“中国天眼”落成启用当日发来贺信，向参加研制和建设的广大科技工作者、工程技术人员、建设者表示热烈的祝贺和诚挚的问候。总书记指出，500米口径球面射电望远镜被誉为“中国天眼”，是具有我国自主知识产权、世界最大单口径、最灵敏的射电望远镜。它的落成启用，对我国在科学前沿实现重大原创突破、加快创新驱动发展具有重要意义。 浩瀚星空，广袤苍穹，自古以来寄托着人类的科…"
