    "description": "新华社贵阳9月25日电 题：黔山贵水见证长征中的军民鱼水情 新华社记者李惊亚、施钱贵 在位于贵州的遵义红军烈士陵园里，一座挂满红绸的铜像静静矗立：一名红军卫生员怀抱孩童、手持汤匙，俯身喂药。铜像的原型，是红三军团红军卫生员龙思泉。 在过去很长一段时间，不少人以为龙思泉是一名女性。“老百姓对这位红军战士充满感情，亲切称她‘小红’，常有人烧香祭拜，表达追思。”遵义红军烈士陵园讲解员杨彤说，“实际上，龙思泉是一名男性。” 1935年1月，中央…",
    "content": "新华社贵阳9月25日电 题：黔山贵水见证长征中的军民鱼水情 新华社记者李惊亚、施钱贵 在位于贵州的遵义红军烈士陵园里，一座挂满红绸的铜像静静矗立：一名红军卫生员怀抱孩童、手持汤匙，俯身喂药。铜像的原型，是红三军团红军卫生员龙思泉。 在过去很长一段时间，不少人以为龙思泉是一名女性。“老百姓对这位红军战士充满感情，亲切称她‘小红’，常有人烧香祭拜，表达追思。”遵义红军烈士陵园讲解员杨彤说，“实际上，龙思泉是一名男性。” 1935年1月，中央红军进驻黔北重镇遵义。身为红军卫生员的龙思泉始终把乡亲们的病痛冷暖放在心上，不分…"
