    "description": "9月25日，“中国天眼”——500米口径球面射电望远镜（FAST）迎来落成十周年。 波兰著名射电天文学家亚历山大·沃尔什钱日前接受新华社采访时点赞“中国天眼”。他表示，中国现在拥有世界上最大的单口径射电望远镜——FAST，其灵敏度远高于其他同类射电望远镜，在脉冲星研究、系外行星探测等领域将发挥重要作用。 记者：杨钰晨、郭爽 新华社音视频部制作",
