    "content": "新华社日本名古屋9月25日电（记者赵紫羽）爱知·名古屋亚运会25日结束滑板项目碗池决赛的争夺，中国队女子选手曹诗祺、孟令妍分获第四名和第六名，杭州亚运会冠军陈烨位列男子第八名。 决赛每名运动员有三轮比赛机会，第三轮结束后，排名前五的运动员进入第四轮“黄金轮”。运动员最终成绩为四轮（前三轮及“黄金轮”）中最佳一轮的成绩。 在率先进行的女子碗池决赛中，曹诗祺在第一轮拿到73.03分排名第三，随后两轮均出现失误，前三轮后位列第五，进入“黄金轮”。曹诗祺在最后一轮滑出81.23分，最终获得第四名。 曹诗祺是本届亚运会中国体…"
