    "description": "当地时间9月24日上午，国家主席习近平同美国总统特朗普在白宫举行会谈。习近平主席指出，我和特朗普总统一直通过各种方式保持沟通，共同为中美关系这艘大船领航掌舵。习近平主席就让中美建设性战略稳定关系更好惠及两国人民和世界各国人民作出重要论述——",
    "content": "当地时间9月24日上午，国家主席习近平同美国总统特朗普在白宫举行会谈。习近平主席指出，我和特朗普总统一直通过各种方式保持沟通，共同为中美关系这艘大船领航掌舵。习近平主席就让中美建设性战略稳定关系更好惠及两国人民和世界各国人民作出重要论述——"
