    "content": "金秋时节，云南省开远市的稻田遍地鎏金。在航拍的移轴视角下，农人弯腰挥镰，农机往来轰鸣，广袤田野宛如童话般的微型世界，呈现出金秋田园的“微观丰景”。 作者：刘雅龙 摄制：陶家淇 画面来源：云南省开远市融媒体中心 新华社音视频部制作"
