    "pub_date": "2026-09-25 14:46:11",
    "author": "齐菲,宋晨,梁建华",
    "description": "三秋恰半，圆月如期。中秋节之际，一片清辉之下，澳门全城亮起璀璨花灯，邀市民旅客一起同庆佳节，共祝团圆。 记者：齐菲、宋晨 报道员：梁建华 新华社音视频部制作",
    "content": "三秋恰半，圆月如期。中秋节之际，一片清辉之下，澳门全城亮起璀璨花灯，邀市民旅客一起同庆佳节，共祝团圆。 记者：齐菲、宋晨 报道员：梁建华 新华社音视频部制作"
