    "content": "当地时间9月24日，瑞典药物递送平台公司Nanexa宣布，已与诺和诺德就使用PharmaShell技术平台针对某些靶向肥胖、2型糖尿病和其他心脏代谢适应症的肽类药物达成全球独家许可和合作协议。该协议包括最多五个开发项目，并涵盖不同的给药频率方案，以每月和每季度给药为目标方案。诺和诺德将主导全球开发和商业化，Nanexa有资格获得总计最高达11.65亿欧元的付款，其中包括6.15亿欧元的首付款以及开发和监管里程碑付款。其余里程碑付款为销售里程碑付款。此外，Nanexa有资格获得协议项下开发产品全球净销售额的低个位数百…"
