    "description": "新华社贵阳9月25日电 题：困牛山上的纵身一跃 新华社记者李凡 秋日的困牛山，群山叠翠，碧水潺潺。在困牛山红军壮举纪念碑前，来此瞻仰缅怀的红色研学团队络绎不绝。山脚下，宽阔的柏油路直通村口，一栋栋新居错落有致。 这处如今远近闻名的红色美丽村庄，在90余年前关联着一段悲壮的过往。1934年10月，作为长征先遣队的红六军团，行进至贵州石阡县境内，陷入敌人重兵包围。为掩护军团主力突围，红十八师师长龙云、五十二团团长田海清率领数百名红军战士断后…",
    "content": "新华社贵阳9月25日电 题：困牛山上的纵身一跃 新华社记者李凡 秋日的困牛山，群山叠翠，碧水潺潺。在困牛山红军壮举纪念碑前，来此瞻仰缅怀的红色研学团队络绎不绝。山脚下，宽阔的柏油路直通村口，一栋栋新居错落有致。 这处如今远近闻名的红色美丽村庄，在90余年前关联着一段悲壮的过往。1934年10月，作为长征先遣队的红六军团，行进至贵州石阡县境内，陷入敌人重兵包围。为掩护军团主力突围，红十八师师长龙云、五十二团团长田海清率领数百名红军战士断后，将敌军牵制在地势险峻的困牛山。 敌人久攻不下，胁迫当地老百姓做人肉盾牌，将红军…"
