    "content": "新华社华盛顿9月24日电 “中美关系希望在人民、未来在青年。这里，我愿宣布，未来5年，中方将邀请10万名美国青少年来华交流学习。”正在美国进行国事访问的习近平主席24日在白宫欢迎仪式上致辞时说。 当地时间9月24日上午，美国总统特朗普在白宫举行隆重仪式，热烈欢迎中国国家主席习近平对美国进行国事访问。这是习近平致辞。新华社记者 李响 摄 这是习近平主席继2023年11月在旧金山宣布“未来5年邀请5万名美国青少年来华交流学习”倡议之后，又一次面向美国青少年发出新的邀约。 “这是了不起的举措！”习近平主席在艾奥瓦州的老朋…"
