    "title": "日本10年期国债收益率一度升至3.115%",
    "link": "https://36kr.com/newsflashes/3998381187288966?f=rss",
    "pub_date": "2026-09-25 13:59:50",
    "author": "",
    "description": "据日本方面消息，在25日的东京债券市场上，作为长期利率指标的新发10年期国债收益率一度升至3.115%。据日本相互证券公司统计，这是自1996年8月以来的最高水平。国债收益率与价格呈反向关系，收益率升高意味着债券价格下跌。（央视新闻）",
    "content": "据日本方面消息，在25日的东京债券市场上，作为长期利率指标的新发10年期国债收益率一度升至3.115%。据日本相互证券公司统计，这是自1996年8月以来的最高水平。国债收益率与价格呈反向关系，收益率升高意味着债券价格下跌。（央视新闻）"
