    "content": "24日，国乒男团以2:3负于东道主日本队，无缘亚运会男团九连冠。决赛失利，再次暴露出中国男乒当下过度依赖王楚钦、阵容深度不足等问题短板。 出征本届亚运会的国乒男队，仅王楚钦一人拥有亚运会参赛经历，林诗栋、温瑞博等队员均是首次踏上亚运赛场。事实上，在决赛负于日本队之前，国乒男队就已遭遇险情。四分之一决赛中，主力林诗栋爆冷不敌泰国16岁新星普里查扬；半决赛对阵中国台北队，王楚钦在先赢两局的大好局面下被林昀儒连追两局，决胜局鏖战至15:13才惊险闯关。 决赛对手日本队近两年进步迅速，已成为中国男队在亚洲乃至世界范围内的头…"
