    "author": "王铭禹",
    "description": "新华社兰州9月25日电（记者王铭禹）中秋佳节，人们的餐桌上自然少不了月饼，在市面上新式月饼种类繁多、不断推陈出新的当下，不少人依然偏爱用料扎实、口味地道的本地传统老月饼。在甘肃兰州，传统手工月饼守住老味道、留住老情怀，创新文创月饼融入本土文化、贴合现代审美，一守一创之间，丰富了当地的“中秋味道”。 清晨，天还没透亮，在兰州市七里河区的一条小巷内，“姥姥家的土月饼”作坊门前早已排起了长队。不足二十平方米的小店内灯火通明，57岁的店主杨兰与…",
    "content": "新华社兰州9月25日电（记者王铭禹）中秋佳节，人们的餐桌上自然少不了月饼，在市面上新式月饼种类繁多、不断推陈出新的当下，不少人依然偏爱用料扎实、口味地道的本地传统老月饼。在甘肃兰州，传统手工月饼守住老味道、留住老情怀，创新文创月饼融入本土文化、贴合现代审美，一守一创之间，丰富了当地的“中秋味道”。 清晨，天还没透亮，在兰州市七里河区的一条小巷内，“姥姥家的土月饼”作坊门前早已排起了长队。不足二十平方米的小店内灯火通明，57岁的店主杨兰与丈夫一早就忙碌起来，揉面、醒面、兑碱、擀皮、铺料、叠层……一道道古法工序有条不紊…"
