    "description": "新华社“雪龙2”号9月25日电（记者温竞华）记者从中国第16次北冰洋考察队获悉，考察队近日在北冰洋加拿大海盆区域开展年度调查时发现，今年该区域50米至100米深度的次表层水温度显著高于以往同期。 “雪龙2”号海洋队队长陈红霞说，本航次延续了对西经169度这一历史观测断面的年度观测，通过温盐深仪对海洋水体进行了跨越6至7个纬度的垂直剖面观测，观测结果为评估流入北冰洋的太平洋水的年际变化提供了依据。 中国第9次至第15次北冰洋考察采集的数据…",
    "content": "新华社“雪龙2”号9月25日电（记者温竞华）记者从中国第16次北冰洋考察队获悉，考察队近日在北冰洋加拿大海盆区域开展年度调查时发现，今年该区域50米至100米深度的次表层水温度显著高于以往同期。 “雪龙2”号海洋队队长陈红霞说，本航次延续了对西经169度这一历史观测断面的年度观测，通过温盐深仪对海洋水体进行了跨越6至7个纬度的垂直剖面观测，观测结果为评估流入北冰洋的太平洋水的年际变化提供了依据。 中国第9次至第15次北冰洋考察采集的数据显示，该区域50米至100米深度的次表层水温度均在零下1.75度至零下1.15度…"
