    "content": "新华社武汉9月25日电 题：“高山流水”处 两岸共月圆 新华社记者乐文婉 中秋前夜，月满江城，丹桂飘香。24日晚，“月是故乡明——鄂台婚姻家庭中秋联谊活动”在武汉古琴台举行。40余名两岸婚姻家庭成员，以及台湾湖北同乡会、武汉同乡会的乡亲围坐一团，一道喜迎中秋、共话团圆。 古琴声起，清越悠扬。春秋战国时期，俞伯牙与钟子期“高山流水遇知音”的佳话发源于武汉，古琴台因此得名。 对于台商甘品洋和妻子郑芳来说，知音就在身边。郑芳是湖北恩施人，13年前，两人在武汉步入婚姻殿堂。“重回武汉，就会回想起我们相识的故事。”甘品洋笑着…"
