    "content": "新华社日本名古屋9月25日电 题：五次通关“打平就出线”，安东尼奥做对了什么 新华社记者肖世尧、王海洲 本届亚运会男足小组赛前两轮，中国队1胜1平积4分，末轮对阵阿联酋队，只需战平便可锁定出线名额。 “打平就出线”——一句寻常不过的积分形势分析，却瞬间让中国球迷绷紧了神经。 曾几何时，“打平就出线”是中国足球多年挥之不去的噩梦。 1985年，墨西哥世界杯预选赛小组赛末轮，中国队只要在主场战平中国香港队即可出线，最终却以1:2告负，成为中国足球史上最著名的悲剧之一；1992年，巴塞罗那奥运会预选赛，中国队打平韩国队即…"
