    "content": "新华社科伦坡9月25日电（记者陈冬书）马累消息：马尔代夫总统穆伊兹24日在马累表示，马尔代夫高度重视同中国的长期友好关系，期待同中方共同应对挑战、把握机遇，进一步巩固传统友谊。 穆伊兹当天出席中国驻马尔代夫大使馆举办的庆祝中华人民共和国成立77周年招待会，并向中国政府和人民致以国庆祝贺。穆伊兹说，中国走过了一段坚韧不拔、深刻变革的非凡历程，凭借坚定意志和远见卓识为世界作出重要贡献，在经济发展、科技、基础设施建设和民生福祉等领域取得的成就广受认可。 穆伊兹表示，对马尔代夫人民而言，对华友谊“看得见、摸得着，并且惠及日…"
