    "author": "秦黛新",
    "description": "9月16日至24日，舟山东极岛35千伏蓬中线/蓬柱线开展计划性检修，东极微电网迎来实战考验。国网舟山供电公司提前部署，增派2台2000千瓦集装箱式应急发电车，通过浮吊船吊装至庙子湖北岙码头，启动东极微电网2台1500千瓦柴油发电机组，与岛上1兆瓦储能、1兆瓦光伏协同出力，确保检修期间海岛供电不间断。 国网舟山供电公司东极供电服务站站长王春银介绍：“东极岛远离大陆，35千伏海缆是唯一的上级电源通道。此次上级线路检修期间，我们依托全国首个自…",
    "content": "9月16日至24日，舟山东极岛35千伏蓬中线/蓬柱线开展计划性检修，东极微电网迎来实战考验。国网舟山供电公司提前部署，增派2台2000千瓦集装箱式应急发电车，通过浮吊船吊装至庙子湖北岙码头，启动东极微电网2台1500千瓦柴油发电机组，与岛上1兆瓦储能、1兆瓦光伏协同出力，确保检修期间海岛供电不间断。 国网舟山供电公司东极供电服务站站长王春银介绍：“东极岛远离大陆，35千伏海缆是唯一的上级电源通道。此次上级线路检修期间，我们依托全国首个自愈式海岛智慧微电网，实现‘大网检修、孤网自保’。2台2000千瓦发电车作为应急后…"
