    "author": "刘诗平",
    "description": "新华社北京9月25日电 中央气象台25日预报，中秋假期，华西至黄淮、江淮有持续性降雨，青藏高原有较强雨雪天气，华北和东北地区有小到中雨、局地大雨，华北中南部、黄淮中西部、西北地区东部、四川盆地等地有大雾天气，出行注意安全。 中央气象台预计，25日至27日，陕西南部、四川东北部、重庆中北部、湖北西部和北部、河南中南部、山东南部、安徽中北部、江苏等地有中雨，部分地区有大到暴雨。华西秋雨持续时间较长，部分地区累计雨量较大，发生地质灾害气象风险…",
    "content": "新华社北京9月25日电 中央气象台25日预报，中秋假期，华西至黄淮、江淮有持续性降雨，青藏高原有较强雨雪天气，华北和东北地区有小到中雨、局地大雨，华北中南部、黄淮中西部、西北地区东部、四川盆地等地有大雾天气，出行注意安全。 中央气象台预计，25日至27日，陕西南部、四川东北部、重庆中北部、湖北西部和北部、河南中南部、山东南部、安徽中北部、江苏等地有中雨，部分地区有大到暴雨。华西秋雨持续时间较长，部分地区累计雨量较大，发生地质灾害气象风险较高。 同时，青藏高原大部地区有小到中雨（雪）或雨夹雪。其中，西藏山南市南部、日…"
