    "pub_date": "2026-09-25 11:11:16",
    "author": "龙泠宇,李帅,毛俊",
    "description": "《旅游强国建设“十五五”规划》提出，到2030年，国内居民出游人次达到83亿，国内出游总花费达到7.7万亿元，旅游的普惠性进一步凸显。未来五年，旅游会有哪些新变化？一起来看看。 ■更惠民 门槛更低 规划首次提出旅游普惠性的目标。未来，通过降低旅游门槛、促进服务便利化等措施，群众将有更多机会参与到旅游活动中。此外，规划顺应体验类消费需求增强的趋势，就丰富优质旅游产品供给作出部署，融合业态更丰富。 9月16日，游客在湖北襄阳古城游览参观。新…",
