    "content": "新华社印度尼西亚图阿尔9月25日电（记者李嘉聪）中印尼渔业捕捞合作启动仪式24日在印度尼西亚马鲁古省图阿尔市举行。 当天，来自两国政府、企业以及当地渔业协会的百余名代表齐聚位于班达海与阿拉弗拉海交界处的一座渔港。随着启动按钮被按下，数艘来自中国的现代化渔船鸣响汽笛，在人群的欢呼声中驶向深海。 中国驻印尼使馆公使衔参赞李洪伟在启动仪式上表示，中方提出的共建21世纪海上丝绸之路倡议与印尼“全球海洋支点”构想高度契合，双方积极推动战略对接、规划对接、产业对接和项目对接，共建海洋命运共同体。中方愿以此次渔业捕捞合作启动为契…"
