    "content": "新华社日本名古屋9月25日电（记者曹奕博、王镜宇）中国男篮在爱知·名古屋亚运会半决赛负于日本队后，前欧洲职业球员哈恰图良逐帧拆解了球队战术执行中的漏洞，复盘了中国队的10个技战术方面的问题。 哈恰图良曾代表亚美尼亚国家队参加国际篮联比赛，拥有篮球专项的体育科学硕士学位，在中国从事篮球教学近9年。以下是他总结归纳的10个问题： 一、接球后犹豫 中国队球员接球后常常要停顿1到2秒才决定下一步动作，这个短暂的迟疑足以让防守方完成协防和补位调整。哈恰图良的建议很直接：接球之前，脑子里就应该想好要做什么。 二、缺少无球跑动 …"
